// /jei says what this build is; /jei give turns "Click gives items" on or off.
fn jei_command(game: &mut crate::game::Game<'_>, command: &str, ran: &mut bool) {
    use crate::game::jei as m;
    let Some(args) = command.strip_prefix("jei") else {
        return;
    };
    if !(args.is_empty() || args.starts_with(' ')) {
        return;
    }
    let Some(cmd) = m::command(args) else {
        *ran = true;
        game.native_chat("Unknown option: use /jei or /jei give");
        return;
    };
    *ran = true;
    match cmd {
        m::Command::About => {
            let text = match crate::game::jei_glue::counts() {
                Some((items, recipes)) => m::about_counts(items, recipes),
                None => m::about(),
            };
            game.native_chat(&text);
        }
        m::Command::ToggleGive => {
            let on = m::give(game.native_setting(m::ID, "give").as_deref());
            game.native_set_setting(m::ID, "give", if on { "false" } else { "true" });
            game.native_chat(&m::give_button(!on));
        }
    }
}

// The zoom in effect, unless another mod's came first.
fn zoom_view(game: &crate::game::Game<'_>, zoom: &mut Option<crate::game::native_hooks::NativeZoom>) {
    if zoom.is_none()
        && game.native_on(crate::game::official_zoom::ID)
        && let Some((factor, smooth, turn)) = crate::game::official_zoom::view()
    {
        *zoom = Some(crate::game::native_hooks::NativeZoom {
            factor,
            smooth,
            turn,
        });
    }
}

// The minimap Horizon draws for the mod, unless another mod's came first.
fn minimap_view(game: &crate::game::Game<'_>, minimap: &mut Option<crate::game::native_hooks::NativeMinimap>) {
    use crate::game::official_minimap as m;
    use horizon_client::extras::Corner;
    // Turned off in Options > Mods: nothing until the next build leaves it out.
    if minimap.is_some() || !game.native_on(m::ID) {
        return;
    }
    let settings = m::settings(|key| game.native_setting(m::ID, key));
    let (size, blocks_per_pixel) = settings.view();
    *minimap = Some(crate::game::native_hooks::NativeMinimap {
        corner: [Corner::TopLeft, Corner::TopRight, Corner::BottomLeft, Corner::BottomRight][settings.corner],
        size,
        blocks_per_pixel,
        rotate: settings.rotate,
        round: settings.round,
    });
}

