// A click on the settings page: 0 turns "Click gives items" on or off, 1
// switches the language.
fn jei_click(game: &mut crate::game::Game<'_>, mod_id: &str, button: usize) {
    use crate::game::jei as m;
    if mod_id != m::ID {
        return;
    }
    match button {
        0 => {
            let on = m::give(game.native_setting(m::ID, "give").as_deref());
            game.native_set_setting(m::ID, "give", if on { "false" } else { "true" });
        }
        1 => {
            let lang = m::lang(game.native_setting(m::ID, "language").as_deref());
            game.native_set_setting(m::ID, "language", lang.next().code());
        }
        _ => {}
    }
}

// A click on the mod's settings page: change the setting and keep it.
fn official_minimap_click(game: &mut crate::game::Game<'_>, mod_id: &str, button: usize) {
    use crate::game::official_minimap as m;
    if mod_id != m::ID {
        return;
    }
    let mut settings = m::settings(|key| game.native_setting(m::ID, key));
    settings.click(button);
    m::set_settings(settings);
    for (key, value) in settings.stored() {
        game.native_set_setting(m::ID, key, &value);
    }
}

// A click on motion blur's settings page: the next choice, in effect at once and kept.
fn motion_blur_click(game: &mut crate::game::Game<'_>, mod_id: &str, button: usize) {
    use horizon_client::gfx::native_render::motion_blur as mb;
    if mod_id != mb::ID {
        return;
    }
    let mut settings = mb::settings();
    settings.click(button);
    mb::set_settings(settings);
    for (key, value) in settings.stored() {
        game.native_set_setting(mb::ID, key, &value);
    }
}

