fn queue(action: Action) {
    PENDING.with_borrow_mut(|p| p.push(action));
}

fn click_sound() {
    queue(Action::Sound);
}

fn hit([x, y, w, h]: [f32; 4], [mx, my]: [f32; 2]) -> bool {
    mx >= x && mx < x + w && my >= y && my < y + h
}

/// A config screen is up.
