// The edges between Horizon and the viewer (crate::game::jei): the game's
// item and recipe tables in, the panel, give and place out.
use crate::game::jei::{
    self, Context, Event, Ingredient, Item, Kind, Layout, Out, Recipe, Stack, View, Viewer,
};
use crate::game::native_hooks::{
    NativePanelEvent, NativeRecipeKind, NativeRecipeLayout, NativeRecipeStack, NativeRecipeView,
    NativeRecipes, NativeStack,
};
use std::cell::RefCell;

/// The viewer while a world is open.
struct State {
    viewer: Option<Viewer>,
}

thread_local! {
    static STATE: RefCell<State> = const { RefCell::new(State { viewer: None }) };
}

/// Builds the viewer once per world and shows the item list in the panel.
pub(super) fn sync(game: &mut crate::game::Game<'_>) {
    if !game.native_on(jei::ID) {
        return;
    }
    if game.native_player().is_none() {
        STATE.with(|s| s.borrow_mut().viewer = None);
        return;
    }
    if STATE.with(|s| s.borrow().viewer.is_some()) {
        return;
    }
    let Some(catalog) = game.native_recipes() else {
        return;
    };
    let lang = jei::lang(game.native_setting(jei::ID, "language").as_deref());
    let (viewer, out) = Viewer::new(items(&catalog), recipes(&catalog), lang);
    STATE.with(|s| s.borrow_mut().viewer = Some(viewer));
    if let Err(error) = apply(game, out) {
        game.native_chat(&format!("JEI: {error}"));
    }
}

/// The panel's events: search, clicks, R/U, tabs, pages and the action button.
pub(super) fn event(game: &mut crate::game::Game<'_>, event: &NativePanelEvent) {
    if !game.native_on(jei::ID) {
        return;
    }
    let Some(event) = convert_event(event) else {
        return;
    };
    let known = game.native_known_recipes();
    let recipe_key = game.native_mod_key(jei::ID, "recipe", "key.keyboard.r");
    let uses_key = game.native_mod_key(jei::ID, "uses", "key.keyboard.u");
    let give = jei::give(game.native_setting(jei::ID, "give").as_deref());
    let lang = jei::lang(game.native_setting(jei::ID, "language").as_deref());
    let ctx = Context {
        recipe_key: &recipe_key,
        uses_key: &uses_key,
        give,
        // `native_give` succeeds in creative only: try, and fall back below.
        creative: give,
        known: &known,
    };

    let mut fallback = false;
    for out in handle(&event, &ctx, lang) {
        if let Out::Give { item, count } = out {
            if game.native_give(&item, count).is_err() {
                fallback = true;
            }
            continue;
        }
        if let Err(error) = apply(game, out) {
            game.native_chat(&format!("JEI: {error}"));
        }
    }
    if fallback {
        // Survival: the same click opens the recipes, as JEI without cheat mode.
        let ctx = Context {
            give: false,
            creative: false,
            ..ctx
        };
        for out in handle(&event, &ctx, lang) {
            if let Err(error) = apply(game, out) {
                game.native_chat(&format!("JEI: {error}"));
            }
        }
    }
}

fn handle(event: &Event, ctx: &Context<'_>, lang: jei::Lang) -> Vec<Out> {
    STATE.with(|s| {
        let mut state = s.borrow_mut();
        let Some(viewer) = state.viewer.as_mut() else {
            return Vec::new();
        };
        viewer.set_lang(lang);
        viewer.handle(event.clone(), ctx)
    })
}

/// The viewer's size, for `/jei`; none outside a world.
pub(super) fn counts() -> Option<(usize, usize)> {
    STATE.with(|s| {
        s.borrow()
            .viewer
            .as_ref()
            .map(|viewer| (viewer.item_count(), viewer.recipe_count()))
    })
}

fn apply(game: &mut crate::game::Game<'_>, out: Out) -> Result<(), String> {
    match out {
        Out::Items(stacks) => {
            game.native_panel_items(jei::ID, panel_stacks(stacks));
            Ok(())
        }
        Out::Recipes {
            title,
            tabs,
            tab,
            views,
        } => {
            game.native_panel_recipes(
                jei::ID,
                &title,
                to_native(tabs),
                tab,
                views.into_iter().map(native_view).collect(),
            );
            Ok(())
        }
        Out::Give { item, count } => game.native_give(&item, count),
        Out::Place { book_id, all } => game.native_place_recipe(book_id, all),
        Out::Say(text) => {
            game.native_chat(&text);
            Ok(())
        }
    }
}

/// The game's stacks. An empty list keeps one invisible slot: the panel (and
/// its search box and events) goes away when the list is empty.
fn panel_stacks(stacks: Vec<Stack>) -> Vec<NativeStack> {
    if stacks.is_empty() {
        return vec![NativeStack {
            item: "minecraft:air".to_owned(),
            count: 0,
            components: String::new(),
        }];
    }
    to_native(stacks)
}

fn to_native(stacks: Vec<Stack>) -> Vec<NativeStack> {
    stacks
        .into_iter()
        .map(|s| NativeStack {
            item: s.item,
            count: s.count,
            components: s.components,
        })
        .collect()
}

fn native_view(view: View) -> NativeRecipeView {
    NativeRecipeView {
        layout: match view.layout {
            Layout::Grid => NativeRecipeLayout::Grid,
            Layout::Cooking => NativeRecipeLayout::Cooking,
            Layout::Single => NativeRecipeLayout::Single,
            Layout::Smithing => NativeRecipeLayout::Smithing,
            Layout::Brewing => NativeRecipeLayout::Brewing,
        },
        width: view.width,
        height: view.height,
        slots: view.slots.into_iter().map(to_native).collect(),
        results: to_native(view.results),
        note: view.note,
        action: view.action,
    }
}

fn convert_event(event: &NativePanelEvent) -> Option<Event> {
    Some(match event {
        NativePanelEvent::Search(text) => Event::Search(text.clone()),
        NativePanelEvent::Clicked { index, right } => Event::Clicked {
            index: *index as usize,
            right: *right,
        },
        NativePanelEvent::Key { key, stack } => Event::Key {
            key: key.clone(),
            stack: stack_of(stack),
        },
        NativePanelEvent::Tab(tab) => Event::Tab(*tab as usize),
        NativePanelEvent::Back => Event::Back,
        NativePanelEvent::SlotClicked { stack, right, .. } => Event::SlotClicked {
            stack: stack_of(stack),
            right: *right,
        },
        NativePanelEvent::Action(index) => Event::Action(*index as usize),
        _ => return None,
    })
}

fn stack_of(stack: &NativeStack) -> Stack {
    Stack {
        item: stack.item.clone(),
        count: stack.count,
        components: stack.components.clone(),
    }
}

fn items(catalog: &NativeRecipes) -> Vec<Item> {
    catalog
        .items
        .iter()
        .map(|item| Item {
            id: item.id.clone(),
            name: item.name.clone(),
            tags: item.tags.clone(),
        })
        .collect()
}

fn recipes(catalog: &NativeRecipes) -> Vec<Recipe> {
    catalog
        .recipes
        .iter()
        // A recipe with no ingredients says nothing in a list of recipes.
        .filter(|recipe| !recipe.slots.is_empty())
        .map(|recipe| Recipe {
            kind: kind(recipe.kind),
            width: recipe.width,
            height: recipe.height,
            slots: ingredient_slots(&recipe.slots),
            results: ingredient_list(&recipe.results),
            cooking_time: recipe.cooking_time,
            experience: recipe.experience,
            book_id: recipe.book_id,
        })
        .collect()
}

fn ingredient_slots(slots: &[Vec<NativeRecipeStack>]) -> Vec<Vec<Ingredient>> {
    slots.iter().map(|slot| ingredient_list(slot)).collect()
}

fn ingredient_list(stacks: &[NativeRecipeStack]) -> Vec<Ingredient> {
    stacks
        .iter()
        .map(|stack| Ingredient {
            item: stack.item,
            count: stack.count,
            components: stack.components.clone(),
        })
        .collect()
}

fn kind(kind: NativeRecipeKind) -> Kind {
    match kind {
        NativeRecipeKind::CraftingShaped => Kind::CraftingShaped,
        NativeRecipeKind::CraftingShapeless => Kind::CraftingShapeless,
        NativeRecipeKind::Smelting => Kind::Smelting,
        NativeRecipeKind::Blasting => Kind::Blasting,
        NativeRecipeKind::Smoking => Kind::Smoking,
        NativeRecipeKind::Campfire => Kind::Campfire,
        NativeRecipeKind::Stonecutting => Kind::Stonecutting,
        NativeRecipeKind::Smithing => Kind::Smithing,
        NativeRecipeKind::Brewing => Kind::Brewing,
    }
}

#[allow(dead_code)]
pub const ID: &str = "appleskin";
#[allow(dead_code)]
pub const NAME: &str = "AppleSkin";
#[allow(dead_code)]
pub const VERSION: &str = "0.1.3";
#[allow(dead_code)]
pub const DESCRIPTION: &str = "Saturation, exhaustion and the food in your hand, drawn over the food bar as the original AppleSkin does.";

pub const MAX_FOOD: i32 = 20;
pub const MAX_HEALTH: f32 = 20.0;
pub const MAX_EXHAUSTION: f32 = 4.0;
pub const REGEN_EXHAUSTION: f32 = 6.0;

pub const FOOD_RIGHT: f32 = 91.0;
pub const FOOD_ROW_BOTTOM: f32 = 39.0;
pub const ICON: f32 = 9.0;
pub const ICON_STEP: f32 = 8.0;
pub const ICON_HALF_COLS: usize = 4;

pub const STRIP_WIDTH: usize = 81;
pub const STRIP_HEIGHT: usize = 9;
pub const STRIP_COLOR: u32 = 0x8F28_2828;

pub const PREVIEW_DIM: f32 = 0.7;
pub const CEILING_ALPHA: f32 = 0.35;
pub const FADE_MS: f32 = 300.0;
pub const PULSE_MS: u128 = 1000;
pub const PULSE_DEPTH: f32 = 0.4;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Animation {
    Fade,
    Pulse,
    Both,
}

impl Animation {
    pub fn for_code(code: &str) -> Self {
        match code {
            "fade" => Self::Fade,
            "pulse" => Self::Pulse,
            "both" => Self::Both,
            _ => Self::Both,
        }
    }

    pub fn code(self) -> &'static str {
        match self {
            Self::Fade => "fade",
            Self::Pulse => "pulse",
            Self::Both => "both",
        }
    }

    pub fn next(self) -> Self {
        match self {
            Self::Fade => Self::Pulse,
            Self::Pulse => Self::Both,
            Self::Both => Self::Fade,
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Self::Fade => "fade",
            Self::Pulse => "pulse",
            Self::Both => "fade + pulse",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Eaten {
    pub food: i32,
    pub saturation: f32,
}

pub fn eaten(food: i32, saturation: f32, nutrition: u32, added: f32) -> Eaten {
    let food = (food + nutrition as i32).clamp(0, MAX_FOOD);
    Eaten {
        food,
        saturation: (saturation + added).clamp(0.0, food as f32),
    }
}

pub fn exhaustion_shown(visible: bool, exhaustion: f32) -> Option<f32> {
    (visible && exhaustion.is_finite()).then(|| exhaustion.clamp(0.0, MAX_EXHAUSTION))
}

pub fn strip_width(exhaustion: f32) -> usize {
    (exhaustion.clamp(0.0, MAX_EXHAUSTION) / MAX_EXHAUSTION * STRIP_WIDTH as f32) as usize
}

pub fn saturation_frame(share: f32) -> usize {
    if share >= 1.0 {
        3
    } else if share > 0.5 {
        2
    } else if share > 0.25 {
        1
    } else {
        0
    }
}

pub fn saturation_gain_start(saturation: f32) -> usize {
    (saturation.clamp(0.0, MAX_FOOD as f32) / 2.0).floor() as usize
}

pub fn saturation_icons(saturation: f32) -> impl Iterator<Item = (usize, usize)> {
    let s = saturation.clamp(0.0, MAX_FOOD as f32) / 2.0;
    (0..s.ceil() as usize).map(move |i| (i, saturation_frame(s - i as f32)))
}

pub fn food_icons(from: i32, to: i32) -> impl Iterator<Item = (usize, bool)> {
    (from / 2..(to + 1) / 2).map(move |i| (i as usize, i * 2 + 1 == to))
}

pub fn heart_icons(from: f32, to: f32) -> impl Iterator<Item = (usize, bool)> {
    let start = (from.ceil() / 2.0).floor() as i32;
    let end = (to.ceil() / 2.0).ceil() as i32;
    let whole = to.ceil() as i32;
    (start..end).map(move |i| (i as usize, i * 2 + 1 == whole))
}

pub fn approach(alpha: f32, target: f32, dt_ms: f32) -> f32 {
    let step = dt_ms / FADE_MS;
    if alpha < target {
        (alpha + step).min(target)
    } else {
        (alpha - step).max(target)
    }
}

pub fn brightness(animation: Animation, present: bool, alpha: f32, now_ms: u128) -> f32 {
    let phase = (now_ms % PULSE_MS) as f32 / PULSE_MS as f32 * std::f32::consts::TAU;
    let pulse = 0.5 - 0.5 * phase.cos();
    match animation {
        Animation::Fade => alpha,
        Animation::Pulse => {
            if present {
                1.0 - PULSE_DEPTH * pulse
            } else {
                0.0
            }
        }
        Animation::Both => {
            let ramp = ((alpha - 0.9) / 0.1).clamp(0.0, 1.0);
            alpha * (1.0 - PULSE_DEPTH * pulse * ramp)
        }
    }
}

pub fn fade(argb: u32, alpha: f32) -> u32 {
    let a = ((argb >> 24) as f32 * alpha) as u32;
    (a << 24) | (argb & 0x00FF_FFFF)
}

pub fn dim(argb: u32, factor: f32) -> u32 {
    let scale = |c: u32| ((c as f32) * factor) as u32;
    let r = scale((argb >> 16) & 0xFF);
    let g = scale((argb >> 8) & 0xFF);
    let b = scale(argb & 0xFF);
    (argb & 0xFF00_0000) | (r << 16) | (g << 8) | b
}

pub fn regeneration_heal(duration: i32, amplifier: i32) -> f32 {
    (duration / (50 >> (amplifier & 31)).max(1)) as f32
}

pub fn estimated_heal(mut food: i32, mut saturation: f32, mut exhaustion: f32, natural: bool) -> f32 {
    if !natural || !exhaustion.is_finite() || !saturation.is_finite() {
        return 0.0;
    }
    let mut health = 0.0;
    while food >= 18 {
        while exhaustion > MAX_EXHAUSTION {
            exhaustion -= MAX_EXHAUSTION;
            if saturation > 0.0 {
                saturation = (saturation - 1.0).max(0.0);
            } else {
                food -= 1;
            }
        }
        if food >= 20 && saturation > f32::MIN_POSITIVE {
            let limited = saturation.min(REGEN_EXHAUSTION);
            let until = MAX_EXHAUSTION.next_up() - exhaustion;
            let iterations = ((until / limited).ceil() as i32).max(1) as f32;
            health += limited / REGEN_EXHAUSTION * iterations;
            exhaustion += limited * iterations;
        } else if food >= 18 {
            health += 1.0;
            exhaustion += REGEN_EXHAUSTION;
        }
    }
    health
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Options {
    pub saturation: bool,
    pub exhaustion: bool,
    pub preview: bool,
    pub animation: Animation,
}

pub const KEYS: [&str; 4] = ["numbers", "bars", "preview", "animation"];

impl Default for Options {
    fn default() -> Self {
        Self {
            saturation: true,
            exhaustion: true,
            preview: true,
            animation: Animation::Both,
        }
    }
}

impl Options {
    pub fn from_settings(get: impl Fn(&str) -> Option<String>) -> Self {
        let on = |key: &str| !matches!(get(key).as_deref(), Some("off"));
        Self {
            saturation: on(KEYS[0]),
            exhaustion: on(KEYS[1]),
            preview: on(KEYS[2]),
            animation: Animation::for_code(get(KEYS[3]).as_deref().unwrap_or("")),
        }
    }

    pub fn get(&self, index: usize) -> bool {
        match index {
            0 => self.saturation,
            1 => self.exhaustion,
            _ => self.preview,
        }
    }
}

pub fn flag_text(on: bool) -> &'static str {
    if on { "on" } else { "off" }
}

pub fn labels(options: Options) -> Vec<String> {
    let names = ["Saturation icons", "Exhaustion strip", "Held food preview"];
    let mut out: Vec<String> = names
        .iter()
        .enumerate()
        .map(|(i, name)| format!("{name}: {}", flag_text(options.get(i))))
        .collect();
    out.push(format!("Animation: {}", options.animation.name()));
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn eating_caps_food_and_saturation_as_the_game_does() {
        let e = eaten(18, 1.0, 6, 3.6);
        assert_eq!(e.food, 20);
        assert!((e.saturation - 4.6).abs() < 1e-5);
        let e = eaten(0, 0.0, 0, 0.0);
        assert_eq!((e.food, e.saturation), (0, 0.0));
    }

    #[test]
    fn saturation_never_exceeds_the_food_left() {
        let e = eaten(4, 3.0, 2, 10.0);
        assert_eq!(e.food, 6);
        assert_eq!(e.saturation, 6.0);
    }

    #[test]
    fn exhaustion_is_shown_only_where_the_game_counts_it() {
        assert_eq!(exhaustion_shown(true, 2.5), Some(2.5));
        assert_eq!(exhaustion_shown(false, 2.5), None);
        assert_eq!(exhaustion_shown(true, f32::NAN), None);
        assert_eq!(exhaustion_shown(true, 7.0), Some(MAX_EXHAUSTION));
    }

    #[test]
    fn strip_shows_the_exhaustion_share_of_81_pixels() {
        assert_eq!(strip_width(0.0), 0);
        assert_eq!(strip_width(2.0), 40);
        assert_eq!(strip_width(4.0), 81);
    }

    #[test]
    fn saturation_frames_change_at_the_original_thresholds() {
        assert_eq!(saturation_frame(1.0), 3);
        assert_eq!(saturation_frame(0.75), 2);
        assert_eq!(saturation_frame(0.5), 1);
        assert_eq!(saturation_frame(0.25), 0);
    }

    #[test]
    fn saturation_icons_cover_the_saturation_in_pairs() {
        assert_eq!(saturation_icons(0.0).count(), 0);
        let frames: Vec<usize> = saturation_icons(5.0).map(|(_, f)| f).collect();
        assert_eq!(frames, vec![3, 3, 1]);
    }

    #[test]
    fn saturation_gain_redraws_the_partly_filled_icon() {
        assert_eq!(saturation_gain_start(4.6), 2);
        assert_eq!(saturation_gain_start(4.0), 2);
        assert_eq!(saturation_gain_start(0.0), 0);
    }

    #[test]
    fn food_icons_cover_the_food_points_restored() {
        let v: Vec<_> = food_icons(10, 16).collect();
        assert_eq!(v, vec![(5, false), (6, false), (7, false)]);
        let v: Vec<_> = food_icons(10, 15).collect();
        assert_eq!(v, vec![(5, false), (6, false), (7, true)]);
        assert_eq!(food_icons(20, 20).count(), 0);
    }

    #[test]
    fn heart_icons_mark_the_half_heart_at_the_end() {
        let v: Vec<_> = heart_icons(10.0, 13.0).collect();
        assert_eq!(v, vec![(5, false), (6, true)]);
        assert_eq!(heart_icons(20.0, 20.0).count(), 0);
    }

    #[test]
    fn dim_darkens_colour_and_keeps_alpha() {
        assert_eq!(dim(0xFFFF_FFFF, 0.5), 0xFF7F_7F7F);
        assert_eq!(dim(0x80FF_0000, 1.0), 0x80FF_0000);
    }

    #[test]
    fn fade_moves_toward_the_target_and_stops_there() {
        assert!((approach(0.0, 1.0, FADE_MS / 2.0) - 0.5).abs() < 1e-6);
        assert_eq!(approach(0.9, 1.0, 10_000.0), 1.0);
        assert_eq!(approach(0.5, 0.0, 10_000.0), 0.0);
    }

    #[test]
    fn fade_scales_only_the_alpha_byte() {
        assert_eq!(fade(0xFF10_2030, 0.5), 0x7F10_2030);
        assert_eq!(fade(0xFF10_2030, 0.0) >> 24, 0);
    }

    #[test]
    fn fade_animation_is_the_plain_alpha() {
        assert_eq!(brightness(Animation::Fade, true, 0.4, 0), 0.4);
        assert_eq!(brightness(Animation::Fade, false, 0.4, 500), 0.4);
    }

    #[test]
    fn pulse_breathes_between_full_and_dimmed_while_present() {
        assert!((brightness(Animation::Pulse, true, 0.0, 0) - 1.0).abs() < 1e-5);
        assert!((brightness(Animation::Pulse, true, 0.0, 500) - 0.6).abs() < 1e-5);
        assert_eq!(brightness(Animation::Pulse, false, 1.0, 0), 0.0);
    }

    #[test]
    fn both_fades_in_first_then_pulses() {
        assert_eq!(brightness(Animation::Both, true, 0.5, 500), 0.5);
        assert!((brightness(Animation::Both, true, 1.0, 500) - 0.6).abs() < 1e-5);
    }

    #[test]
    fn animation_cycles_and_round_trips_its_key() {
        for a in [Animation::Fade, Animation::Pulse, Animation::Both] {
            assert_eq!(Animation::for_code(a.code()), a);
        }
        let mut a = Animation::Both;
        let mut seen = Vec::new();
        for _ in 0..3 {
            a = Animation::for_code(a.next().code());
            seen.push(a);
        }
        assert_eq!(seen, vec![Animation::Fade, Animation::Pulse, Animation::Both]);
        assert_eq!(Animation::for_code("nonsense"), Animation::Both);
        assert_eq!(Animation::Fade.next().next().next(), Animation::Fade);
    }

    #[test]
    fn regeneration_heal_follows_the_game_tick_count() {
        assert_eq!(regeneration_heal(900, 0), 18.0);
        assert_eq!(regeneration_heal(900, 1), 36.0);
        assert_eq!(regeneration_heal(100, 6), 100.0);
    }

    #[test]
    fn slow_regen_heals_one_health_per_iteration_at_eighteen_food() {
        assert_eq!(estimated_heal(18, 0.0, 0.0, true), 1.0);
        assert_eq!(estimated_heal(17, 0.0, 0.0, true), 0.0);
    }

    #[test]
    fn no_natural_regeneration_means_no_estimate() {
        assert_eq!(estimated_heal(20, 10.0, 0.0, false), 0.0);
    }

    #[test]
    fn estimate_is_zero_for_nonfinite_input_and_stays_finite() {
        assert_eq!(estimated_heal(20, 5.0, f32::NAN, true), 0.0);
        assert!(estimated_heal(20, 10.0, 3.9, true).is_finite());
    }

    #[test]
    fn settings_default_to_on_and_read_off() {
        let all = Options::from_settings(|_| None);
        assert_eq!(all, Options::default());
        let some = Options::from_settings(|key| (key == "bars").then(|| "off".to_owned()));
        assert!(!some.exhaustion);
        assert!(some.saturation && some.preview);
    }

    #[test]
    fn animation_setting_is_read_from_its_key() {
        let both = Options::from_settings(|key| (key == "animation").then(|| "both".to_owned()));
        assert_eq!(both.animation, Animation::Both);
    }

    #[test]
    fn labels_follow_keys() {
        let all = labels(Options::default());
        assert_eq!(all.len(), KEYS.len());
        assert_eq!(all[0], "Saturation icons: on");
        assert_eq!(all[3], "Animation: fade + pulse");
        let off = Options { exhaustion: false, ..Options::default() };
        assert_eq!(labels(off)[1], "Exhaustion strip: off");
    }

    #[test]
    fn fade_and_pulse_is_the_default_animation() {
        assert_eq!(Options::default().animation, Animation::Both);
        assert_eq!(Options::from_settings(|_| None).animation, Animation::Both);
    }
}

use crate::game::Game;
use crate::game::official_appleskin as aps;
use crate::game::official_appleskin_icons as icons;
use horizon_client::hud::HudBatch;
use std::sync::Mutex;

#[derive(Clone, Copy)]
struct Shown {
    food: i32,
    saturation: f32,
    eaten: aps::Eaten,
    health: f32,
    heal: f32,
}

struct Fade {
    alpha: f32,
    last_ms: u128,
    shown: Option<Shown>,
}

static FADE: Mutex<Fade> = Mutex::new(Fade {
    alpha: 0.0,
    last_ms: 0,
    shown: None,
});

fn wall_millis() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_millis())
}

fn advance(current: Option<Shown>, now: u128) -> (f32, Option<Shown>) {
    let mut fade = FADE.lock().unwrap_or_else(|e| e.into_inner());
    let dt = if fade.last_ms == 0 {
        0.0
    } else {
        now.saturating_sub(fade.last_ms).min(100) as f32
    };
    fade.last_ms = now;
    fade.alpha = aps::approach(fade.alpha, if current.is_some() { 1.0 } else { 0.0 }, dt);
    if let Some(s) = current {
        fade.shown = Some(s);
    } else if fade.alpha <= 0.0 {
        fade.shown = None;
    }
    (fade.alpha, fade.shown)
}

fn anchors(batch: &HudBatch) -> (f32, f32, f32) {
    let w = batch.width as f32;
    (
        w / 2.0 + aps::FOOD_RIGHT,
        w / 2.0 - aps::FOOD_RIGHT,
        batch.height as f32 - aps::FOOD_ROW_BOTTOM,
    )
}

impl Game<'_> {
    fn appleskin_options(&self) -> aps::Options {
        aps::Options::from_settings(|key| self.native_setting(aps::ID, key))
    }

    fn appleskin_sprite(&self, batch: &mut HudBatch, x: f32, y: f32, grid: &[&str], half: bool, look: (f32, f32)) {
        let (dim, alpha) = look;
        let cols = if half { aps::ICON_HALF_COLS } else { aps::ICON as usize };
        for (row, line) in grid.iter().enumerate() {
            let line = line.as_bytes();
            let mut col = 0;
            while col < cols {
                let ch = line[col];
                let start = col;
                while col < cols && line[col] == ch {
                    col += 1;
                }
                if ch != b'.' {
                    let argb = aps::fade(aps::dim(icons::color(ch), dim), alpha);
                    let rect = [x + start as f32, y + row as f32, (col - start) as f32, 1.0];
                    self.native_fill(batch, rect, argb);
                }
            }
        }
    }

    fn appleskin_preview(&self, batch: &mut HudBatch, s: Shown, level: f32) {
        let (right, left, top) = anchors(batch);
        let look = (aps::PREVIEW_DIM, level);

        let food: Vec<(usize, bool)> = aps::food_icons(s.food, s.eaten.food).collect();
        for &(i, half) in &food {
            let x = right - aps::ICON - aps::ICON_STEP * i as f32;
            self.appleskin_sprite(batch, x, top, icons::FOOD, half, look);
        }

        let from = aps::saturation_gain_start(s.saturation);
        for (i, frame) in aps::saturation_icons(s.eaten.saturation) {
            if i < from || food.iter().any(|&(j, _)| j == i) {
                continue;
            }
            let x = right - aps::ICON - aps::ICON_STEP * i as f32;
            self.appleskin_sprite(batch, x, top, icons::SATURATION[frame], false, look);
        }

        if s.health > 0.0 && s.health < aps::MAX_HEALTH {
            let faint = (aps::PREVIEW_DIM, level * aps::CEILING_ALPHA);
            for (i, half) in aps::heart_icons(s.health, aps::MAX_HEALTH) {
                let x = left + aps::ICON_STEP * i as f32;
                self.appleskin_sprite(batch, x, top, icons::HEART, half, faint);
            }
        }
        if s.heal > 0.0 {
            let modified = (s.health + s.heal).min(aps::MAX_HEALTH);
            for (i, half) in aps::heart_icons(s.health, modified) {
                let x = left + aps::ICON_STEP * i as f32;
                self.appleskin_sprite(batch, x, top, icons::HEART, half, look);
            }
        }
    }

    pub(super) fn appleskin_bar(&self, batch: &mut HudBatch) {
        if self.ui.hide_gui
            || !self.native_on(aps::ID)
            || !self.native_playing()
            || self.creative
            || matches!(self.mode, horizon_client::command::args::GameMode::Spectator)
        {
            return;
        }
        let Some(h) = self.native_hunger() else {
            return;
        };
        let opts = self.appleskin_options();
        let (right, _, top) = anchors(batch);
        let shown_exhaustion = aps::exhaustion_shown(h.exhaustion_visible, h.exhaustion);

        if opts.exhaustion {
            if let Some(e) = shown_exhaustion {
                let width = aps::strip_width(e);
                let first = aps::STRIP_WIDTH - width;
                for col in first..aps::STRIP_WIDTH {
                    let x = right - width as f32 + (col - first) as f32;
                    for y in 0..aps::STRIP_HEIGHT {
                        if (col + y) % 2 == 1 {
                            self.native_fill(batch, [x, top + y as f32, 1.0, 1.0], aps::STRIP_COLOR);
                        }
                    }
                }
            }
        }

        if opts.saturation {
            for (i, frame) in aps::saturation_icons(h.saturation) {
                let x = right - aps::ICON - aps::ICON_STEP * i as f32;
                self.appleskin_sprite(batch, x, top, icons::SATURATION[frame], false, (1.0, 1.0));
            }
        }

        let current = match h.held {
            Some((nutrition, added)) if opts.preview => {
                let eaten = aps::eaten(h.food, h.saturation, nutrition, added);
                let allowed = h.food < 18
                    && h.health > 0.0
                    && h.health < aps::MAX_HEALTH
                    && !h.peaceful
                    && !h.regeneration_blocked;
                let heal = if allowed {
                    aps::estimated_heal(
                        eaten.food,
                        eaten.saturation,
                        shown_exhaustion.unwrap_or(0.0),
                        h.natural_regeneration,
                    ) + h.held_regeneration.map_or(0.0, |(d, a)| aps::regeneration_heal(d, a))
                } else {
                    0.0
                };
                Some(Shown {
                    food: h.food,
                    saturation: h.saturation,
                    eaten,
                    health: h.health,
                    heal,
                })
            }
            _ => None,
        };

        let now = wall_millis();
        let (alpha, shown) = advance(current, now);
        let level = aps::brightness(opts.animation, current.is_some(), alpha, now);
        if let Some(s) = shown.filter(|_| level > 0.0) {
            self.appleskin_preview(batch, s, level);
        }
    }

    pub(super) fn appleskin_settings(&self) -> Vec<String> {
        aps::labels(self.appleskin_options())
    }

    pub(super) fn appleskin_settings_click(&mut self, button: usize) {
        let options = self.appleskin_options();
        if button == 3 {
            self.native_set_setting(aps::ID, aps::KEYS[3], options.animation.next().code());
            return;
        }
        let Some(key) = aps::KEYS.get(button) else {
            return;
        };
        let on = options.get(button);
        self.native_set_setting(aps::ID, key, aps::flag_text(!on));
    }
}

use crate::game::Game;

#[derive(Clone, Copy, Debug)]
pub struct NativeHunger {
    pub food: i32,
    pub saturation: f32,
    pub exhaustion: f32,
    pub exhaustion_visible: bool,
    pub health: f32,
    pub held: Option<(u32, f32)>,
    pub held_regeneration: Option<(i32, i32)>,
    pub natural_regeneration: bool,
    pub peaceful: bool,
    pub regeneration_blocked: bool,
}

impl Game<'_> {
    pub(super) fn native_hunger(&self) -> Option<NativeHunger> {
        let p = self.player.as_ref()?;
        let food = &p.health.food;
        let held_item = self.held().and_then(|stack| self.res.items().get(&*stack.item));
        let held = held_item.and_then(|info| info.food);
        let held_regeneration = held_item
            .and_then(|info| info.consumable.as_ref())
            .and_then(|consumable| {
                consumable.effects.iter().find_map(|effect| match effect {
                    horizon_client::items::ConsumeEffect::ApplyEffects { effects, .. } => effects
                        .iter()
                        .find(|e| horizon_client::brewing::effect(&e.id).is_some_and(|d| d.id == "regeneration"))
                        .map(|e| (e.duration, e.amplifier)),
                    _ => None,
                })
            });
        let rules = self.world.health_rules;
        let active = &self.potions.effects;
        Some(NativeHunger {
            food: food.food,
            saturation: food.saturation,
            exhaustion: food.exhaustion,
            exhaustion_visible: !p.client_side,
            health: p.health.health(),
            held,
            held_regeneration,
            natural_regeneration: rules.natural_regeneration,
            peaceful: rules.difficulty == horizon_world::food::Difficulty::Peaceful,
            regeneration_blocked: ["poison", "wither", "regeneration"]
                .iter()
                .any(|id| active.get(id).is_some()),
        })
    }
}

// Horizon's official Minimap, formerly the WebAssembly mod and before that a
// built-in extra: a map of the terrain around the player in a corner, in map
// colours, square or round, north up or turning with the player, drawn by
// Horizon's own minimap. Its settings are the WebAssembly mod's files
// (`horizon-mods/.horizon-mod-data/minimap/corner`, `size`, `shape`, `zoom`,
// `rotate`), so a player keeps them. This file is both the mod's Cargo
// library (its tests) and the module the bundle adds to the game.

/// The mod's id (its settings folder), name and version.
pub const ID: &str = "minimap";
pub const NAME: &str = "Minimap";
pub const VERSION: &str = "2.0.0";
pub const DESCRIPTION: &str = "A map of the terrain around you in a corner, in map colours, square or round, north up or turning with you. Horizon's own.";
/// The corners, as the settings files name them and the page labels them.
pub const CORNERS: [(&str, &str); 4] = [
    ("top_left", "Top left"),
    ("top_right", "Top right"),
    ("bottom_left", "Bottom left"),
    ("bottom_right", "Bottom right"),
];
/// Sides in GUI pixels, and blocks per map pixel.
pub const SIZES: [(u8, &str); 3] = [(64, "Small"), (96, "Medium"), (128, "Large")];
pub const ZOOMS: [f32; 4] = [0.5, 1.0, 2.0, 4.0];

/// The settings, as the WebAssembly Minimap kept them.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Settings {
    /// Indices in `CORNERS`, `SIZES` and `ZOOMS`.
    pub corner: usize,
    pub size: usize,
    pub round: bool,
    pub zoom: usize,
    pub rotate: bool,
}

impl Settings {
    /// From the stored values; the extra's defaults (top right, medium,
    /// square, 1 block per pixel, north up) for the ones missing.
    pub fn read(get: impl Fn(&str) -> Option<String>) -> Self {
        let get = |key: &str| get(key).map(|v| v.trim().to_owned());
        let find = |key: &str, values: &[String], default: usize| {
            get(key)
                .and_then(|v| values.iter().position(|s| *s == v))
                .unwrap_or(default)
        };
        let corners: Vec<String> = CORNERS.iter().map(|c| c.0.to_owned()).collect();
        let sizes: Vec<String> = SIZES.iter().map(|s| s.0.to_string()).collect();
        let zooms: Vec<String> = ZOOMS.iter().map(f32::to_string).collect();
        Self {
            corner: find("corner", &corners, 1),
            size: find("size", &sizes, 1),
            round: get("shape").as_deref() == Some("round"),
            zoom: find("zoom", &zooms, 1),
            rotate: get("rotate").as_deref() == Some("true"),
        }
    }
    pub fn labels(&self) -> Vec<String> {
        let n = ZOOMS[self.zoom];
        let blocks = if n < 1.0 {
            "½ block".to_owned()
        } else if n == 1.0 {
            "1 block".to_owned()
        } else {
            format!("{n} blocks")
        };
        vec![
            format!("Corner: {}", CORNERS[self.corner].1),
            format!("Size: {}", SIZES[self.size].1),
            format!("Shape: {}", if self.round { "Round" } else { "Square" }),
            format!("Zoom: {blocks} per pixel"),
            format!(
                "Turn with the player: {}",
                if self.rotate { "ON" } else { "OFF" }
            ),
        ]
    }
    pub fn click(&mut self, i: usize) {
        let next = |i: usize, n: usize| (i + 1) % n;
        match i {
            0 => self.corner = next(self.corner, CORNERS.len()),
            1 => self.size = next(self.size, SIZES.len()),
            2 => self.round = !self.round,
            3 => self.zoom = next(self.zoom, ZOOMS.len()),
            4 => self.rotate = !self.rotate,
            _ => {}
        }
    }
    pub fn stored(&self) -> [(&'static str, String); 5] {
        [
            ("corner", CORNERS[self.corner].0.to_owned()),
            ("size", SIZES[self.size].0.to_string()),
            (
                "shape",
                if self.round { "round" } else { "square" }.to_owned(),
            ),
            ("zoom", ZOOMS[self.zoom].to_string()),
            (
                "rotate",
                if self.rotate { "true" } else { "false" }.to_owned(),
            ),
        ]
    }
    /// What Horizon's minimap draws: (side, blocks per pixel).
    pub fn view(&self) -> (f32, f32) {
        (f32::from(SIZES[self.size].0), ZOOMS[self.zoom])
    }
}

thread_local! {
    /// The settings, read once from the files, then kept.
    static SETTINGS: std::cell::Cell<Option<Settings>> = const { std::cell::Cell::new(None) };
}

/// The settings, read once through `get` (one file per key).
pub fn settings(get: impl Fn(&str) -> Option<String>) -> Settings {
    SETTINGS.with(|s| {
        let found = s.get().unwrap_or_else(|| Settings::read(get));
        s.set(Some(found));
        found
    })
}

/// Replaces the settings (the settings page changed them).
pub fn set_settings(settings: Settings) {
    SETTINGS.with(|s| s.set(Some(settings)));
}

